var o=`0594-khuushuur`;var i=`world-0594`;var t=`MN`;var a=`east-asia`;var l=4;var r=63;var u={en:`Khuushuur`,ua:`Хуушуур`};var s={en:`A traditional dish from Mongolia, centered on all-purpose flour, ground lamb, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Монголія. Основні складники: пшеничне борошно універсальне, фарш з ягнятини, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 18 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 18 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:18,i:[[`all-purpose-flour`,390,`g`],[`water`,170,`ml`],[`table-salt`,6,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`ground-lamb`,530,`g`],[`yellow-onion`,250,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:18,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 15 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 15 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:15,i:[[`sunflower-oil`,680,`ml`]]}];var d={slug:o,id:i,country:`MN`,region:a,servings:4,minutes:63,title:u,text:s,steps:g};export{t as country,d as default,i as id,r as minutes,a as region,l as servings,o as slug,g as steps,s as text,u as title};